// ReTrace marketing site + support form, served from a single Worker.
//
// Routes:
//   GET  /            marketing page (hero, features, screenshots, privacy, support)
//   GET  /privacy     same page, scrolled to the Privacy Policy section
//                      -> use this as the "Privacy Policy URL" in App Store Connect
//   GET  /support     same page, scrolled to the Support section
//                      -> use this as the "Support URL" in App Store Connect
//   POST /api/contact submits the support form, emails SUPPORT_EMAIL via Resend
//
// Setup:
//   1. Create a free account at https://resend.com and generate an API key.
//   2. From this folder: wrangler secret put RESEND_API_KEY
//   3. (Optional) verify your own sending domain in Resend, then set
//      CONTACT_FROM_EMAIL as a var in wrangler.toml, e.g.
//      "ReTrace <support@rtrace.xyz>". Until then, the Resend sandbox
//      address onboarding@resend.dev is used, which works without a
//      verified domain.
//   4. SUPPORT_EMAIL below is where form submissions land — either point it
//      at a real inbox you own, or set up Cloudflare Email Routing for
//      support@rtrace.xyz to forward to your real address.

const SUPPORT_EMAIL = "support@rtrace.xyz";
const PAGE_ROUTES = new Set(["/", "/index.html", "/privacy", "/support"]);

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (request.method === "GET" && PAGE_ROUTES.has(url.pathname)) {
      return new Response(HTML, {
        headers: {
          "content-type": "text/html; charset=UTF-8",
          "cache-control": "public, max-age=3600",
        },
      });
    }

    if (request.method === "POST" && url.pathname === "/api/contact") {
      return handleContact(request, env);
    }

    return new Response("Not found", { status: 404 });
  },
};

async function handleContact(request, env) {
  let body;
  try {
    body = await request.json();
  } catch (err) {
    return jsonResponse({ ok: false, error: "Invalid request." }, 400);
  }

  const email = (body.email || "").toString().trim();
  const message = (body.message || "").toString().trim();
  const honeypot = (body.website || "").toString().trim();

  // Bots fill hidden fields; pretend success without actually sending.
  if (honeypot) {
    return jsonResponse({ ok: true });
  }

  if (!isValidEmail(email)) {
    return jsonResponse({ ok: false, error: "Please enter a valid email address." }, 400);
  }
  if (message.length < 5) {
    return jsonResponse({ ok: false, error: "Please write a short message." }, 400);
  }
  if (message.length > 5000) {
    return jsonResponse({ ok: false, error: "Message is too long." }, 400);
  }

  if (!env.RESEND_API_KEY) {
    return jsonResponse(
      { ok: false, error: "The support form isn't set up yet — please email us directly." },
      500
    );
  }

  const fromAddress = env.CONTACT_FROM_EMAIL || "ReTrace Support <onboarding@resend.dev>";

  const resendResponse = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${env.RESEND_API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from: fromAddress,
      to: [SUPPORT_EMAIL],
      reply_to: email,
      subject: `ReTrace support message from ${email}`,
      text: message,
    }),
  });

  if (!resendResponse.ok) {
    const detail = await resendResponse.text();
    console.error("Resend error:", resendResponse.status, detail);
    return jsonResponse(
      { ok: false, error: "Could not send your message right now. Please try again later." },
      502
    );
  }

  return jsonResponse({ ok: true });
}

function isValidEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=UTF-8" },
  });
}

